//! Doubly linked polygon-ring node, stored in an arena.
//!
//! The reference C++ implementation links nodes with raw pointers and never
//! frees them until the whole triangulation is done, so node identity is stable
//! for the entire run. We reproduce that with a `Vec<Node>` arena where a node
//! is addressed by its slot index; `NIL` plays the role of `nullptr`.

/// Arena index standing in for a null pointer.
pub const NIL: usize = usize::MAX;

#[derive(Clone, Copy)]
pub struct Node {
    /// Index of the vertex in the original input sequence.
    pub i: u32,
    pub x: f64,
    pub y: f64,

    /// Previous and next vertex in the polygon ring.
    pub prev: usize,
    pub next: usize,

    /// Z-order curve value.
    pub z: i32,

    /// Previous and next node in z-order.
    pub prev_z: usize,
    pub next_z: usize,

    /// Whether this is a Steiner point.
    pub steiner: bool,
}

impl Node {
    pub fn new(i: u32, x: f64, y: f64) -> Node {
        Node {
            i,
            x,
            y,
            prev: NIL,
            next: NIL,
            z: 0,
            prev_z: NIL,
            next_z: NIL,
            steiner: false,
        }
    }
}

