//! Geometric predicates shared by the ear-slicing passes.
//!
//! Every predicate takes the arena plus node indices so the arithmetic stays in
//! exactly the same order as the C++ original — the algorithm branches on the
//! sign of these expressions, so reassociating them would change the output.

use super::node::Node;

/// Signed area of the triangle (p, q, r); positive when it winds clockwise.
pub fn area(nodes: &[Node], p: usize, q: usize, r: usize) -> f64 {
    let (p, q, r) = (&nodes[p], &nodes[q], &nodes[r]);
    (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
}

pub fn equals(nodes: &[Node], p1: usize, p2: usize) -> bool {
    nodes[p1].x == nodes[p2].x && nodes[p1].y == nodes[p2].y
}

/// Check whether a point lies within a convex triangle.
#[allow(clippy::too_many_arguments)]
pub fn point_in_triangle(
    ax: f64,
    ay: f64,
    bx: f64,
    by: f64,
    cx: f64,
    cy: f64,
    px: f64,
    py: f64,
) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

fn sign(num: f64) -> i32 {
    if num > 0.0 {
        1
    } else if num < 0.0 {
        -1
    } else {
        0
    }
}

/// For collinear points p, q, r, check whether q lies on the segment pr.
fn on_segment(nodes: &[Node], p: usize, q: usize, r: usize) -> bool {
    let (p, q, r) = (&nodes[p], &nodes[q], &nodes[r]);
    q.x <= p.x.max(r.x) && q.x >= p.x.min(r.x) && q.y <= p.y.max(r.y) && q.y >= p.y.min(r.y)
}

/// Check whether the segments p1q1 and p2q2 intersect.
pub fn intersects(nodes: &[Node], p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
    let o1 = sign(area(nodes, p1, q1, p2));
    let o2 = sign(area(nodes, p1, q1, q2));
    let o3 = sign(area(nodes, p2, q2, p1));
    let o4 = sign(area(nodes, p2, q2, q1));

    if o1 != o2 && o3 != o4 {
        return true; // general case
    }

    // collinear cases: an endpoint of one segment lying on the other
    if o1 == 0 && on_segment(nodes, p1, p2, q1) {
        return true;
    }
    if o2 == 0 && on_segment(nodes, p1, q2, q1) {
        return true;
    }
    if o3 == 0 && on_segment(nodes, p2, p1, q2) {
        return true;
    }
    if o4 == 0 && on_segment(nodes, p2, q1, q2) {
        return true;
    }

    false
}

