//! Hole elimination: each inner ring is joined to the outer ring by a bridge
//! so the whole polygon becomes a single ring that ear slicing can consume.

use super::geom::{area, point_in_triangle};
use super::node::NIL;
use super::Earcut;

impl Earcut {
    /// Link every hole into the outer loop, producing a single-ring polygon.
    pub(super) fn eliminate_holes(&mut self, points: &[Vec<[f64; 2]>], outer_node: usize) -> usize {
        let mut outer_node = outer_node;
        let mut queue: Vec<usize> = Vec::new();

        for ring in points.iter().skip(1) {
            let list = self.linked_list(ring, false);
            if list != NIL {
                if list == self.nodes[list].next {
                    self.nodes[list].steiner = true;
                }
                queue.push(self.get_leftmost(list));
            }
        }

        queue.sort_by(|&a, &b| {
            self.nodes[a]
                .x
                .partial_cmp(&self.nodes[b].x)
                .unwrap_or(std::cmp::Ordering::Equal)
        });

        // process holes from left to right
        for &hole in &queue {
            outer_node = self.eliminate_hole(hole, outer_node);
        }

        outer_node
    }

    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
        let bridge = self.find_hole_bridge(hole, outer_node);
        if bridge == NIL {
            return outer_node;
        }

        let bridge_reverse = self.split_polygon(bridge, hole);

        // filter collinear points around the cuts
        let next = self.nodes[bridge_reverse].next;
        self.filter_points(bridge_reverse, next);
        let next = self.nodes[bridge].next;
        self.filter_points(bridge, next)
    }

    /// David Eberly's algorithm for finding a bridge between hole and outer polygon.
    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
        let mut p = outer_node;
        let hx = self.nodes[hole].x;
        let hy = self.nodes[hole].y;
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;

        // find a segment intersected by a ray from the hole's leftmost point to the left;
        // segment's endpoint with lesser x will be potential connection point
        loop {
            let next = self.nodes[p].next;
            if hy <= self.nodes[p].y && hy >= self.nodes[next].y && self.nodes[next].y != self.nodes[p].y {
                let x = self.nodes[p].x
                    + (hy - self.nodes[p].y) * (self.nodes[next].x - self.nodes[p].x)
                        / (self.nodes[next].y - self.nodes[p].y);
                if x <= hx && x > qx {
                    qx = x;
                    m = if self.nodes[p].x < self.nodes[next].x { p } else { next };
                    if x == hx {
                        // hole touches outer segment; pick leftmost endpoint
                        return m;
                    }
                }
            }
            p = next;
            if p == outer_node {
                break;
            }
        }

        if m == NIL {
            return NIL;
        }

        // look for points inside the triangle of hole point, segment intersection and endpoint;
        // if there are no points found, we have a valid connection;
        // otherwise choose the point of the minimum angle with the ray as connection point
        let stop = m;
        let mx = self.nodes[m].x;
        let my = self.nodes[m].y;
        let mut tan_min = f64::INFINITY;

        p = m;
        loop {
            let px = self.nodes[p].x;
            let py = self.nodes[p].y;
            if hx >= px
                && px >= mx
                && hx != px
                && point_in_triangle(
                    if hy < my { hx } else { qx },
                    hy,
                    mx,
                    my,
                    if hy < my { qx } else { hx },
                    hy,
                    px,
                    py,
                )
            {
                let tan = (hy - py).abs() / (hx - px);

                if self.locally_inside(p, hole)
                    && (tan < tan_min
                        || (tan == tan_min
                            && (px > self.nodes[m].x
                                || (px == self.nodes[m].x && self.sector_contains_sector(m, p)))))
                {
                    m = p;
                    tan_min = tan;
                }
            }

            p = self.nodes[p].next;
            if p == stop {
                break;
            }
        }

        m
    }

    /// Whether sector in vertex m contains sector in vertex p in the same coordinates.
    fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
        let m_prev = self.nodes[m].prev;
        let m_next = self.nodes[m].next;
        let p_prev = self.nodes[p].prev;
        let p_next = self.nodes[p].next;
        area(&self.nodes, m_prev, m, p_prev) < 0.0 && area(&self.nodes, p_next, m, m_next) < 0.0
    }

    /// Find the leftmost node of a polygon ring.
    fn get_leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut leftmost = start;
        loop {
            if self.nodes[p].x < self.nodes[leftmost].x
                || (self.nodes[p].x == self.nodes[leftmost].x
                    && self.nodes[p].y < self.nodes[leftmost].y)
            {
                leftmost = p;
            }
            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }
        leftmost
    }
}

