//! A from-scratch Rust port of the ear-slicing polygon triangulation used by
//! `mapbox::earcut`.
//!
//! The input is a polygon given as a list of rings: the first ring is the outer
//! contour, any further rings are holes. The output is a flat list of vertex
//! indices, three per triangle, numbered over the concatenation of all rings.

mod geom;
mod holes;
mod node;
mod zorder;

use geom::{area, equals, intersects, point_in_triangle};
use node::{Node, NIL};

/// Triangulate a polygon and return the triangle vertex indices.
pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut state = Earcut::new();
    state.run(polygon);
    state.indices
}

pub struct Earcut {
    nodes: Vec<Node>,
    indices: Vec<u32>,
    vertices: usize,

    hashing: bool,
    min_x: f64,
    min_y: f64,
    inv_size: f64,
}

impl Earcut {
    fn new() -> Earcut {
        Earcut {
            nodes: Vec::new(),
            indices: Vec::new(),
            vertices: 0,
            hashing: false,
            min_x: 0.0,
            min_y: 0.0,
            inv_size: 0.0,
        }
    }

    fn run(&mut self, points: &[Vec<[f64; 2]>]) {
        self.indices.clear();
        self.vertices = 0;

        if points.is_empty() {
            return;
        }

        // z-order hashing only pays off past ~80 vertices
        let mut threshold: i32 = 80;
        let mut len: usize = 0;
        let mut i = 0;
        while threshold >= 0 && i < points.len() {
            threshold -= points[i].len() as i32;
            len += points[i].len();
            i += 1;
        }

        self.nodes.reserve(len * 3 / 2);
        self.indices.reserve(len + points[0].len());

        let mut outer_node = self.linked_list(&points[0], true);
        if outer_node == NIL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
            return;
        }

        if points.len() > 1 {
            outer_node = self.eliminate_holes(points, outer_node);
        }

        self.hashing = threshold < 0;
        if self.hashing {
            let mut p = self.nodes[outer_node].next;
            let mut min_x = self.nodes[outer_node].x;
            let mut min_y = self.nodes[outer_node].y;
            let mut max_x = min_x;
            let mut max_y = min_y;
            loop {
                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
                min_x = min_x.min(x);
                min_y = min_y.min(y);
                max_x = max_x.max(x);
                max_y = max_y.max(y);
                p = self.nodes[p].next;
                if p == outer_node {
                    break;
                }
            }

            // min_x, min_y and inv_size are used to transform coords into
            // integers for the z-order calculation
            self.min_x = min_x;
            self.min_y = min_y;
            let size = (max_x - min_x).max(max_y - min_y);
            self.inv_size = if size != 0.0 { 32767.0 / size } else { 0.0 };
        }

        self.earcut_linked(outer_node, 0);

        self.nodes.clear();
    }

    /// Create a circular doubly linked list from polygon points in the
    /// specified winding order.
    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
        let len = points.len();
        let mut last = NIL;

        // calculate original winding order of a polygon ring
        let mut sum = 0.0;
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            let p1 = points[i];
            let p2 = points[j];
            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
            j = i;
        }

        // link points into a circular doubly linked list in the specified order
        if clockwise == (sum > 0.0) {
            for i in 0..len {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        } else {
            for i in (0..len).rev() {
                last = self.insert_node(self.vertices + i, points[i], last);
            }
        }

        if last != NIL && equals(&self.nodes, last, self.nodes[last].next) {
            self.remove_node(last);
            last = self.nodes[last].next;
        }

        self.vertices += len;

        last
    }

    /// Eliminate colinear or duplicate points.
    fn filter_points(&mut self, start: usize, end: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut end = if end == NIL { start } else { end };

        let mut p = start;
        loop {
            let again;

            let prev = self.nodes[p].prev;
            let next = self.nodes[p].next;
            if !self.nodes[p].steiner
                && (equals(&self.nodes, p, next) || area(&self.nodes, prev, p, next) == 0.0)
            {
                self.remove_node(p);
                p = prev;
                end = prev;

                if p == self.nodes[p].next {
                    break;
                }
                again = true;
            } else {
                p = next;
                again = false;
            }

            if !(again || p != end) {
                break;
            }
        }

        end
    }

    /// Main ear slicing loop which triangulates a polygon (given as a linked list).
    fn earcut_linked(&mut self, ear: usize, pass: i32) {
        let mut ear = ear;
        if ear == NIL {
            return;
        }

        // interlink polygon nodes in z-order
        if pass == 0 && self.hashing {
            self.index_curve(ear);
        }

        let mut stop = ear;

        // iterate through ears, slicing them one by one
        while self.nodes[ear].prev != self.nodes[ear].next {
            let prev = self.nodes[ear].prev;
            let next = self.nodes[ear].next;

            let is_ear = if self.hashing {
                self.is_ear_hashed(ear)
            } else {
                self.is_ear(ear)
            };

            if is_ear {
                // cut off the triangle
                self.indices.push(self.nodes[prev].i);
                self.indices.push(self.nodes[ear].i);
                self.indices.push(self.nodes[next].i);

                self.remove_node(ear);

                // skipping the next vertex leads to less sliver triangles
                ear = self.nodes[next].next;
                stop = self.nodes[next].next;

                continue;
            }

            ear = next;

            // if we looped through the whole remaining polygon and can't find any more ears
            if ear == stop {
                if pass == 0 {
                    // try filtering points and slicing again
                    let filtered = self.filter_points(ear, NIL);
                    self.earcut_linked(filtered, 1);
                } else if pass == 1 {
                    // if this didn't work, try curing all small self-intersections locally
                    let filtered = self.filter_points(ear, NIL);
                    let cured = self.cure_local_intersections(filtered);
                    self.earcut_linked(cured, 2);
                } else if pass == 2 {
                    // as a last resort, try splitting the remaining polygon into two
                    self.split_earcut(ear);
                }

                break;
            }
        }
    }

    /// Check whether a polygon node forms a valid ear with adjacent nodes.
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if area(&self.nodes, a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        // now make sure we don't have other points inside the potential ear
        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        let mut p = self.nodes[self.nodes[ear].next].next;
        while p != self.nodes[ear].prev {
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
            if point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
                && area(&self.nodes, pp, p, pn) >= 0.0
            {
                return false;
            }
            p = self.nodes[p].next;
        }

        true
    }

    /// Same as [`Earcut::is_ear`], but only visits candidates whose z-order
    /// falls inside the triangle's bounding box.
    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.nodes[ear].prev;
        let b = ear;
        let c = self.nodes[ear].next;

        if area(&self.nodes, a, b, c) >= 0.0 {
            return false; // reflex, can't be an ear
        }

        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);

        // triangle bbox
        let min_tx = ax.min(bx.min(cx));
        let min_ty = ay.min(by.min(cy));
        let max_tx = ax.max(bx.max(cx));
        let max_ty = ay.max(by.max(cy));

        // z-order range for the current triangle bbox
        let min_z = self.z_order(min_tx, min_ty);
        let max_z = self.z_order(max_tx, max_ty);

        // first look for points inside the triangle in increasing z-order
        let mut p = self.nodes[ear].next_z;
        while p != NIL && self.nodes[p].z <= max_z {
            if p != a && p != c {
                let (px, py) = (self.nodes[p].x, self.nodes[p].y);
                let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
                if point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
                    && area(&self.nodes, pp, p, pn) >= 0.0
                {
                    return false;
                }
            }
            p = self.nodes[p].next_z;
        }

        // then look for points in decreasing z-order
        p = self.nodes[ear].prev_z;
        while p != NIL && self.nodes[p].z >= min_z {
            if p != a && p != c {
                let (px, py) = (self.nodes[p].x, self.nodes[p].y);
                let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
                if point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
                    && area(&self.nodes, pp, p, pn) >= 0.0
                {
                    return false;
                }
            }
            p = self.nodes[p].prev_z;
        }

        true
    }

    /// Go through all polygon nodes and cure small local self-intersections.
    fn cure_local_intersections(&mut self, start: usize) -> usize {
        if start == NIL {
            return start;
        }
        let mut start = start;
        let mut p = start;

        loop {
            let a = self.nodes[p].prev;
            let pnext = self.nodes[p].next;
            let b = self.nodes[pnext].next;

            if !equals(&self.nodes, a, b)
                && intersects(&self.nodes, a, p, pnext, b)
                && self.locally_inside(a, b)
                && self.locally_inside(b, a)
            {
                self.indices.push(self.nodes[a].i);
                self.indices.push(self.nodes[p].i);
                self.indices.push(self.nodes[b].i);

                // remove the two nodes involved
                self.remove_node(p);
                let pnext = self.nodes[p].next;
                self.remove_node(pnext);

                p = b;
                start = b;
            }

            p = self.nodes[p].next;
            if p == start {
                break;
            }
        }

        self.filter_points(p, NIL)
    }

    /// Try splitting the polygon into two and triangulate them independently.
    fn split_earcut(&mut self, start: usize) {
        // look for a valid diagonal that divides the polygon into two
        let mut a = start;
        loop {
            let mut b = self.nodes[self.nodes[a].next].next;
            while b != self.nodes[a].prev {
                if self.nodes[a].i != self.nodes[b].i && self.is_valid_diagonal(a, b) {
                    // split the polygon in two by the diagonal
                    let mut c = self.split_polygon(a, b);

                    // filter colinear points around the cuts
                    let a_next = self.nodes[a].next;
                    a = self.filter_points(a, a_next);
                    let c_next = self.nodes[c].next;
                    c = self.filter_points(c, c_next);

                    // run earcut on each half
                    self.earcut_linked(a, 0);
                    self.earcut_linked(c, 0);
                    return;
                }
                b = self.nodes[b].next;
            }
            a = self.nodes[a].next;
            if a == start {
                break;
            }
        }
    }

    /// Check whether a diagonal connects two polygon nodes and stays inside.
    fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
        let a_next = self.nodes[a].next;
        let a_prev = self.nodes[a].prev;
        let b_prev = self.nodes[b].prev;
        let b_next = self.nodes[b].next;

        self.nodes[a_next].i != self.nodes[b].i
            && self.nodes[a_prev].i != self.nodes[b].i
            && !self.intersects_polygon(a, b) // doesn't intersect other edges
            && ((self.locally_inside(a, b)
                && self.locally_inside(b, a)
                && self.middle_inside(a, b) // locally visible
                // does not create opposite-facing sectors
                && (area(&self.nodes, a_prev, a, b_prev) != 0.0
                    || area(&self.nodes, a, b_prev, b) != 0.0))
                // special zero-length case
                || (equals(&self.nodes, a, b)
                    && area(&self.nodes, a_prev, a, a_next) > 0.0
                    && area(&self.nodes, b_prev, b, b_next) > 0.0))
    }

    /// Check whether a polygon diagonal intersects any polygon segment.
    fn intersects_polygon(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let next = self.nodes[p].next;
            if self.nodes[p].i != self.nodes[a].i
                && self.nodes[next].i != self.nodes[a].i
                && self.nodes[p].i != self.nodes[b].i
                && self.nodes[next].i != self.nodes[b].i
                && intersects(&self.nodes, p, next, a, b)
            {
                return true;
            }
            p = next;
            if p == a {
                break;
            }
        }
        false
    }

    /// Check whether a polygon diagonal is locally inside the polygon.
    fn locally_inside(&self, a: usize, b: usize) -> bool {
        let a_prev = self.nodes[a].prev;
        let a_next = self.nodes[a].next;
        if area(&self.nodes, a_prev, a, a_next) < 0.0 {
            area(&self.nodes, a, b, a_next) >= 0.0 && area(&self.nodes, a, a_prev, b) >= 0.0
        } else {
            area(&self.nodes, a, b, a_prev) < 0.0 || area(&self.nodes, a, a_next, b) < 0.0
        }
    }

    /// Check whether the middle point of a polygon diagonal is inside the polygon.
    fn middle_inside(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px_mid = (self.nodes[a].x + self.nodes[b].x) / 2.0;
        let py_mid = (self.nodes[a].y + self.nodes[b].y) / 2.0;
        loop {
            let next = self.nodes[p].next;
            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
            let (nx, ny) = (self.nodes[next].x, self.nodes[next].y);
            if ((py > py_mid) != (ny > py_mid))
                && ny != py
                && (px_mid < (nx - px) * (py_mid - py) / (ny - py) + px)
            {
                inside = !inside;
            }
            p = next;
            if p == a {
                break;
            }
        }
        inside
    }

    /// Link two polygon vertices with a bridge; if the vertices belong to the
    /// same ring it splits the polygon into two, otherwise it merges rings.
    pub(crate) fn split_polygon(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.new_node(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
        let b2 = self.new_node(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
        let an = self.nodes[a].next;
        let bp = self.nodes[b].prev;

        self.nodes[a].next = b;
        self.nodes[b].prev = a;

        self.nodes[a2].next = an;
        self.nodes[an].prev = a2;

        self.nodes[b2].next = a2;
        self.nodes[a2].prev = b2;

        self.nodes[bp].next = b2;
        self.nodes[b2].prev = bp;

        b2
    }

    fn new_node(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nodes.push(Node::new(i, x, y));
        self.nodes.len() - 1
    }

    /// Create a node and optionally link it with the previous one (in a
    /// circular doubly linked list).
    fn insert_node(&mut self, i: usize, pt: [f64; 2], last: usize) -> usize {
        let p = self.new_node(i as u32, pt[0], pt[1]);

        if last == NIL {
            self.nodes[p].prev = p;
            self.nodes[p].next = p;
        } else {
            let last_next = self.nodes[last].next;
            self.nodes[p].next = last_next;
            self.nodes[p].prev = last;
            self.nodes[last_next].prev = p;
            self.nodes[last].next = p;
        }
        p
    }

    /// Unlink a node from both the ring and the z-order list. The node itself
    /// stays in the arena, so its identity remains valid.
    fn remove_node(&mut self, p: usize) {
        let (prev, next) = (self.nodes[p].prev, self.nodes[p].next);
        self.nodes[next].prev = prev;
        self.nodes[prev].next = next;

        let (prev_z, next_z) = (self.nodes[p].prev_z, self.nodes[p].next_z);
        if prev_z != NIL {
            self.nodes[prev_z].next_z = next_z;
        }
        if next_z != NIL {
            self.nodes[next_z].prev_z = prev_z;
        }
    }
}

