// Entry point mirroring tests/test7.cpp: triangulate a two-turn spiral ring.
//
// The modules under `src/` are pulled in by path so this file builds both with
// a bare `rustc test7.rs` and as the Cargo binary target.

#[path = "src/earcut/mod.rs"]
mod earcut;

use std::f64::consts::PI;
use std::io::Write;

/// Reproduce C's `atoi`: skip leading whitespace, take an optional sign and as
/// many digits as follow, and yield 0 when nothing parses.
fn atoi(s: &str) -> i32 {
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() && (bytes[i] as char).is_whitespace() {
        i += 1;
    }

    let mut negative = false;
    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
        negative = bytes[i] == b'-';
        i += 1;
    }

    let mut value: i32 = 0;
    while i < bytes.len() && bytes[i].is_ascii_digit() {
        let digit = (bytes[i] - b'0') as i32;
        value = value
            .wrapping_mul(10)
            .wrapping_add(if negative { -digit } else { digit });
        i += 1;
    }

    value
}

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut n: i32 = 7;
    if args.len() > 1 {
        n = atoi(&args[1]);
    }

    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
    let mut spiral: Vec<[f64; 2]> = Vec::new();

    let total = n.wrapping_mul(2);
    for i in 0..total {
        let t = i as f64 / total as f64;
        let radius = t;
        let angle = 4.0 * PI * t;
        spiral.push([radius * angle.cos(), radius * angle.sin()]);
    }

    polygon.push(spiral);

    let indices = earcut::earcut(&polygon);

    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::new(stdout.lock());
    for idx in indices {
        write!(out, "{} ", idx).unwrap();
    }
    out.flush().unwrap();
}

